class Solution {
public:
    string baseNeg2(int n) {
        if (n == 0) return "0";
        string res = "";
        while (n != 0) {
            int rem = n % -2;
            n = n / -2;
            if (rem < 0) {
                rem += 2;
                n += 1;
            }
            res.push_back('0' + rem);
        }
        reverse(res.begin(), res.end());
        return res;
    }
};

class Solution {
    public String baseNeg2(int n) {
        if (n == 0) return "0";
        StringBuilder sb = new StringBuilder();
        while (n != 0) {
            int rem = n % -2;
            n = n / -2;
            if (rem < 0) {
                rem += 2;
                n += 1;
            }
            sb.append(rem);
        }
        return sb.reverse().toString();
    }
}

var baseNeg2 = function(n) {
    if (n === 0) return "0";
    const res = [];
    while (n !== 0) {
        let rem = n % -2;
        n = Math.trunc(n / -2);
        if (rem < 0) {
            rem += 2;
            n += 1;
        }
        res.push(rem);
    }
    return res.reverse().join("");
};
